import java.util.Scanner;

public class Main {
    static final int MAXN = 500;
    static int mod_value;
    static int[][] c = new int[MAXN + 1][MAXN + 1];
    static Pair[] dp1_arr = new Pair[MAXN + 1];
    static Pair[][][] dp2_arr = new Pair[2][MAXN + 1][MAXN + 1];

    static class Pair {
        long first;
        long second;

        Pair() {
            this.first = 0;
            this.second = 0;
        }
    }

    static void add_mod(long[] a, long b) {
        a[0] += b;
        if (a[0] >= mod_value) a[0] -= mod_value;
    }

    static long sum_series(long n) {
        return n * (n + 1) >> 1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        mod_value = sc.nextInt();

        for (int i = 0; i <= m; ++i) {
            c[i][0] = 1;
            for (int j = 1; j <= i; ++j) {
                c[i][j] = c[i - 1][j] + c[i - 1][j - 1];
                if (c[i][j] >= mod_value) c[i][j] -= mod_value;
            }
        }

        for (int i = 0; i <= m; ++i) {
            dp1_arr[i] = new Pair();
        }
        dp1_arr[0].first = 1;

        for (int i = 1; i <= m; ++i) {
            for (int j = 1; j <= i; ++j) {
                long w = (dp1_arr[j - 1].first * dp1_arr[i - j].first) % mod_value;
                w = (w * c[i - 1][j - 1]) % mod_value;

                long[] tempSecond = {0};
                add_mod(tempSecond, (sum_series(j - 1) + sum_series(i - j)) * w % mod_value);
                add_mod(tempSecond, (dp1_arr[j - 1].second * dp1_arr[i - j].first) % mod_value * (i + 1) % mod_value * c[i - 1][j - 1]);
                add_mod(tempSecond, (dp1_arr[j - 1].first * dp1_arr[i - j].second) % mod_value * (i + 1) % mod_value * c[i - 1][j - 1]);

                dp1_arr[i].first = (dp1_arr[i].first + w * (i + 1)) % mod_value;
                dp1_arr[i].second = (dp1_arr[i].second + tempSecond[0]) % mod_value;
            }
        }

        for (int i = 0; i < 2; ++i) {
            for (int j = 0; j <= m; ++j) {
                for (int k = 0; k <= m; ++k) {
                    dp2_arr[i][j][k] = new Pair();
                }
            }
        }

        dp2_arr[0][0][0].first = 1;
        dp2_arr[1][0][0].first = 1;

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j <= i; ++j) {
                for (int ln = 1; ln <= n - i; ++ln) {
                    // Update dp2_arr[1]
                    add_mod(new long[]{dp2_arr[1][i + ln][j].first}, dp2_arr[0][i][j].first);
                    add_mod(new long[]{dp2_arr[1][i + ln][j].second}, dp2_arr[0][i][j].second);

                    // Update dp2_arr[0]
                    long val1 = (dp2_arr[1][i][j].first * dp1_arr[ln].first) % mod_value;
                    val1 = (val1 * c[j + ln][j]) % mod_value;
                    add_mod(new long[]{dp2_arr[0][i + ln][j + ln].first}, val1);

                    long val2 = (dp2_arr[1][i][j].first * dp1_arr[ln].second) % mod_value;
                    val2 = (val2 * c[j + ln][j]) % mod_value;
                    add_mod(new long[]{dp2_arr[0][i + ln][j + ln].second}, val2);

                    long val3 = (dp2_arr[1][i][j].second * dp1_arr[ln].first) % mod_value;
                    val3 = (val3 * c[j + ln][j]) % mod_value;
                    add_mod(new long[]{dp2_arr[0][i + ln][j + ln].second}, val3);
                }
            }
        }

        long final_ans = (dp2_arr[0][n][m].second + dp2_arr[1][n][m].second) % mod_value;
        System.out.println(final_ans);
        sc.close();
    }
}
